-- ── Programme ─

CREATE TABLE "festival" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nom" varchar(100) NOT NULL,
    "date_debut" date NOT NULL,
    "date_fin" date NOT NULL,
    CONSTRAINT "festival_dates_check" CHECK ("date_fin" >= "date_debut")
);

CREATE TABLE "lieu" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nom" varchar(100) NOT NULL,
    "adresse" varchar(255) NOT NULL
);

CREATE TABLE "soiree" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "festival_id" integer NOT NULL REFERENCES "festival" ("id"),
    "lieu_id" integer NOT NULL REFERENCES "lieu" ("id"),
    "nom" varchar(100) NOT NULL,
    "thematique" varchar(255) NOT NULL,
    "date_heure_debut" timestamp NOT NULL,
    "capacite" integer NOT NULL CHECK ("capacite" >= 0)
);

CREATE INDEX "soiree_festival_id_idx" ON "soiree" ("festival_id");
CREATE INDEX "soiree_lieu_id_idx" ON "soiree" ("lieu_id");

CREATE TABLE "artiste" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nom" varchar(100) NOT NULL
);

CREATE TABLE "style_musical" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "libelle" varchar(50) NOT NULL UNIQUE
);

CREATE TABLE "spectacle" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "soiree_id" integer NOT NULL REFERENCES "soiree" ("id"),
    "titre" varchar(150) NOT NULL,
    "description" text NOT NULL,
    "url_video" varchar(255) NOT NULL,
    "horaire_previsionnel" time NOT NULL
);

CREATE INDEX "spectacle_soiree_id_idx" ON "spectacle" ("soiree_id");

CREATE TABLE "spectacle_image" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "spectacle_id" integer NOT NULL REFERENCES "spectacle" ("id") ON DELETE CASCADE,
    "url" varchar(255) NOT NULL
);

CREATE INDEX "spectacle_image_spectacle_id_idx" ON "spectacle_image" ("spectacle_id");

CREATE TABLE "spectacle_artiste" (
    "spectacle_id" integer NOT NULL REFERENCES "spectacle" ("id") ON DELETE CASCADE,
    "artiste_id" integer NOT NULL REFERENCES "artiste" ("id") ON DELETE CASCADE,
    PRIMARY KEY ("spectacle_id", "artiste_id")
);

CREATE TABLE "spectacle_style" (
    "spectacle_id" integer NOT NULL REFERENCES "spectacle" ("id") ON DELETE CASCADE,
    "style_id" integer NOT NULL REFERENCES "style_musical" ("id") ON DELETE CASCADE,
    PRIMARY KEY ("spectacle_id", "style_id")
);


-- ── Utilisateurs et tarifs ─

CREATE TABLE "utilisateur" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nom" varchar(100) NOT NULL,
    "email" varchar(255) NOT NULL UNIQUE,
    "mot_de_passe_hash" varchar(255) NOT NULL,
    "role" varchar(20) NOT NULL DEFAULT 'utilisateur'
        CHECK ("role" IN ('utilisateur', 'gestionnaire'))
);

CREATE TABLE "tarif" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "categorie" varchar(10) NOT NULL UNIQUE CHECK ("categorie" IN ('normal', 'reduit')),
    "prix" numeric(6,2) NOT NULL CHECK ("prix" > 0)
);


-- ── Panier ─
-- Un seul panier par utilisateur, supprimé une fois la commande payée.

CREATE TABLE "panier" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "utilisateur_id" integer NOT NULL UNIQUE REFERENCES "utilisateur" ("id") ON DELETE CASCADE
);

CREATE TABLE "ligne_panier" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "panier_id" integer NOT NULL REFERENCES "panier" ("id") ON DELETE CASCADE,
    "soiree_id" integer NOT NULL REFERENCES "soiree" ("id"),
    "tarif_id" integer NOT NULL REFERENCES "tarif" ("id"),
    "quantite" integer NOT NULL CHECK ("quantite" > 0),
    UNIQUE ("panier_id", "soiree_id", "tarif_id")
);

CREATE INDEX "ligne_panier_soiree_id_idx" ON "ligne_panier" ("soiree_id");


-- ── Commande et billets ─
-- La commande est créée à la validation du panier (en_attente).
-- Au paiement, dans une transaction : places vérifiées (soirées verrouillées avec
-- SELECT ... FOR UPDATE), puis billets créés et commande payée, sinon refusée.

CREATE TABLE "commande" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "utilisateur_id" integer NOT NULL REFERENCES "utilisateur" ("id"),
    "panier_id" integer UNIQUE REFERENCES "panier" ("id") ON DELETE SET NULL,
    "reference" varchar(30) NOT NULL UNIQUE,
    "date_commande" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "statut" varchar(15) NOT NULL DEFAULT 'en_attente'
        CHECK ("statut" IN ('en_attente', 'payee', 'refusee')),
    "montant_total" numeric(8,2) NOT NULL CHECK ("montant_total" >= 0)
);

CREATE INDEX "commande_utilisateur_id_idx" ON "commande" ("utilisateur_id");

-- Pass 3 jours : dans un panier avant paiement, rattaché à une commande après.
CREATE TABLE "pass_trois_jours" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "panier_id" integer REFERENCES "panier" ("id") ON DELETE SET NULL,
    "commande_id" integer REFERENCES "commande" ("id"),
    "tarif_id" integer NOT NULL REFERENCES "tarif" ("id"),
    "taux_remise" numeric(4,2) NOT NULL DEFAULT 3.00 CHECK ("taux_remise" >= 0 AND "taux_remise" < 100),
    CONSTRAINT "pass_trois_jours_rattache_check" CHECK ("panier_id" IS NOT NULL OR "commande_id" IS NOT NULL)
);

CREATE INDEX "pass_trois_jours_panier_id_idx" ON "pass_trois_jours" ("panier_id");
CREATE INDEX "pass_trois_jours_commande_id_idx" ON "pass_trois_jours" ("commande_id");

-- Exactement 3 soirées différentes par pass : le nombre est vérifié dans le code.
CREATE TABLE "pass_soiree" (
    "pass_id" integer NOT NULL REFERENCES "pass_trois_jours" ("id") ON DELETE CASCADE,
    "soiree_id" integer NOT NULL REFERENCES "soiree" ("id"),
    PRIMARY KEY ("pass_id", "soiree_id")
);

CREATE TABLE "billet" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "commande_id" integer NOT NULL REFERENCES "commande" ("id"),
    "soiree_id" integer NOT NULL REFERENCES "soiree" ("id"),
    "tarif_id" integer NOT NULL REFERENCES "tarif" ("id"),
    "pass_id" integer REFERENCES "pass_trois_jours" ("id"),
    "reference" varchar(30) NOT NULL UNIQUE,
    "token" char(64) NOT NULL UNIQUE,
    "prix" numeric(6,2) NOT NULL CHECK ("prix" > 0)
);

-- soiree_id : utilisé pour compter les places vendues à chaque achat
CREATE INDEX "billet_soiree_id_idx" ON "billet" ("soiree_id");
CREATE INDEX "billet_commande_id_idx" ON "billet" ("commande_id");
CREATE INDEX "billet_pass_id_idx" ON "billet" ("pass_id");
